export const LOCAL_REFERENCE = {
    /**
     * An ENS declaration's local reference number always starts with "ENS".
     *
     * Only the prefix is asserted. The rest of the reference is generated by the
     * service, and its length is not a contract this suite defends — pinning it
     * would turn a harmless format change into a failing test.
     */
    ENS_PREFIX: /^ENS/,
    DEC_PREFIX: /^DEC/,
    GMR_PREFIX: /^GMR/,
    SUP_PREFIX: /^SUP/,
    GLR_PREFIX: /^GLR/,
    FFD_PREFIX: /^FFD/,
} as const;

/**
 * The country code that opens a Movement Reference Number, by consignment type.
 * An ENS (safety & security) MRN uses "XI"; a Customs (SFD) or IMMI MRN uses
 * "GB". See {@link mrnPrefix}.
 */
export const MRN_COUNTRY_CODE = {
    ENS: 'XI',
    SFD: 'GB',
    IMMI: 'GB',
} as const;

export type MrnCountryCode = (typeof MRN_COUNTRY_CODE)[keyof typeof MRN_COUNTRY_CODE];

/**
 * The opening an MRN must match: the current year's last two digits followed by
 * the type's country code — e.g. in 2026 an ENS MRN starts "26XI", an SFD/IMMI
 * MRN starts "26GB". The year is read at runtime so the rule stays correct as
 * years roll over. Only the opening is asserted; the service-generated remainder
 * is not a contract this suite defends.
 */
export function mrnPrefix(code: MrnCountryCode): RegExp {
    return new RegExp(`^${mrnOpening(code)}`);
}

/**
 * The same opening as text ("26XI"), for a failure message to quote. Built from the
 * one source, so the message can never state a prefix the check does not use.
 */
export function mrnOpening(code: MrnCountryCode): string {
    return `${String(new Date().getFullYear()).slice(-2)}${code}`;
}
